export function applyHunterRevisions<T extends {id:string;effect:string}>(catalog:readonly T[]){
 const byId=new Map<string,typeof hunterRevisions[number]>(hunterRevisions.map(r=>[r.id,r]));
 return catalog.map(old=>{const revision=byId.get(old.id);if(!revision)throw new Error("Missing hunter revision: "+old.id);return {...old,...revision};});
}
